from (
    select thread_id, seq, created_at, content
    from chat_message
    where user_id = 'fd71b9e4-4ea8-5b61-aeb6-cfd65f2da38e'
    offset 0
) filtered
where json.text(json.filter(json.filter(json.filter(content, '$.parts'), 0), '$.text')) like '%partition pruning%'
order by created_at desc, thread_id, seq
limit 50;

