15_part_type_distribution.sql:
select
    part_type,
    count(*) as parts
from (
    select unnest(json_extract_string(content, '$.parts[*].type')) as part_type
    from chat_message
) as exploded
group by part_type
order by parts desc, part_type;

db_overrides.clickhouse:
select tool_name, count(*) as calls
from (
    select arrayJoin(content.parts[].name.:String) as tool_name
    from chat_message
    where content.role = 'assistant'
) as exploded
where isNotNull(tool_name)
group by tool_name
order by calls desc, tool_name;

20_branch_points.sql:
select
    count(*) as branch_points,
    sum(children) as branched_children
from (
    select parent_id, count(*) as children
    from chat_message
    where parent_id is not null
    group by parent_id
    having count(*) > 1
) as branches;

